+import Foundation
+import ApplicationServices
+
+func attr(_ element: AXUIElement, _ name: CFString) -> AnyObject? {
+    var value: CFTypeRef?
+    let err = AXUIElementCopyAttributeValue(element, name, &value)
+    guard err == .success else { return nil }
+    return value
+}
+
+func stringAttr(_ element: AXUIElement, _ name: CFString) -> String? {
+    attr(element, name) as? String
+}
+
+func children(of element: AXUIElement) -> [AXUIElement] {
+    guard let items = attr(element, kAXChildrenAttribute) as? [AXUIElement] else { return [] }
+    return items
+}
+
+func dump(_ element: AXUIElement, depth: Int, limit: Int) {
+    if depth > limit { return }
+    let role = stringAttr(element, kAXRoleAttribute) ?? "?"
+    let title = stringAttr(element, kAXTitleAttribute) ?? stringAttr(element, kAXValueAttribute) ?? ""
+    let desc = stringAttr(element, kAXDescriptionAttribute) ?? ""
+    let indent = String(repeating: "  ", count: depth)
+    print("\(indent)\(role) title=\(title) desc=\(desc)")
+    for child in children(of: element) {
+        dump(child, depth: depth + 1, limit: limit)
+    }
+}
+
+let pid = ProcessInfo.processInfo.environment["PID"].flatMap(Int32.init) ?? 0
+guard pid > 0 else {
+    fputs("Missing PID\n", stderr)
+    exit(1)
+}
+
+let app = AXUIElementCreateApplication(pid)
+print("Trusted: \(AXIsProcessTrusted())")
+if let windows = attr(app, kAXWindowsAttribute) as? [AXUIElement] {
+    print("Windows: \(windows.count)")
+    for (i, win) in windows.enumerated() {
+        print("Window \(i): title=\(stringAttr(win, kAXTitleAttribute) ?? "")")
+        dump(win, depth: 1, limit: 3)
+    }
+} else {
+    print("No windows")
+}
*** End Patch

